      "codigo_refatorado": "using UnityEngine;
using UnityEngine.Rendering;

public class PerformanceGovernor : MonoBehaviour
{
    [Header("Configurações de Resolução Dinâmica")]
    [SerializeField] private float targetFrameTimeMS = 16.0f;
    [SerializeField] private float minResolutionScale = 0.65f;
    [SerializeField] private float maxResolutionScale = 1.0f;
    [SerializeField] private float adjustmentStep = 0.05f;
    [SerializeField] private float sampleInterval = 0.25f;

    private float currentScale = 1.0f;
    private float timer = 0f;
    private float accumulatedFrameTime = 0f;
    private int frameCounter = 0;

    private void Awake()
    {
        QualitySettings.vSyncCount = 0;
        Application.targetFrameRate = 60;
        currentScale = maxResolutionScale;
        ApplyResolutionScale(currentScale);
    }

    private void Update()
    {
        accumulatedFrameTime += Time.unscaledDeltaTime * 1000f;
        frameCounter++;
        timer += Time.unscaledDeltaTime;

        if (timer >= sampleInterval)
        {
            float avgFrameTime = accumulatedFrameTime / Mathf.Max(1, frameCounter);
            EvaluatePerformance(avgFrameTime);
            timer = 0f;
            accumulatedFrameTime = 0f;
            frameCounter = 0;
        }
    }

    private void EvaluatePerformance(float avgFrameTime)
    {
        if (avgFrameTime > targetFrameTimeMS && currentScale > minResolutionScale)
        {
            currentScale = Mathf.Clamp(currentScale - adjustmentStep, minResolutionScale, maxResolutionScale);
            ApplyResolutionScale(currentScale);
        }
        else if (avgFrameTime < (targetFrameTimeMS - 2.5f) && currentScale < maxResolutionScale)
        {
            currentScale = Mathf.Clamp(currentScale + adjustmentStep, minResolutionScale, maxResolutionScale);
            ApplyResolutionScale(currentScale);
        }
    }

    private void ApplyResolutionScale(float scale)
    {
        #if UNITY_2019_1_OR_NEWER
        ScalableBufferManager.ResizeBuffers(scale, scale);
        #else
        int targetWidth = Mathf.RoundToInt(Screen.currentResolution.width * scale);
        int targetHeight = Mathf.RoundToInt(Screen.currentResolution.height * scale);
        Screen.SetResolution(targetWidth, targetHeight, Screen.fullScreen);
        #endif
    }
}",
